    }    else if (value is ChatOptionsMsg) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is UsageMsg) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is ChatResultMsg) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is LiveReadyMsg) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is LivePartialMsg) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is LiveFinalMsg) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    }    else if (value is ChatDeltaMsg) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    }    else if (value is VoiceListeningMsg) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    }    else if (value is VoiceHeardMsg) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    }    else if (value is VoiceThinkingMsg) {
