      writeValue(buffer, value.encode());
    }    else if (value is VoiceReplyMsg) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    }    else if (value is VoiceDoneMsg) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : LanguageMsg.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : RoleMsg.values[value];
      case 131:
        return ConfigMsg.decode(readValue(buffer)!);
      case 132:
        return SegmentMsg.decode(readValue(buffer)!);
      case 133:
        return TranscriptMsg.decode(readValue(buffer)!);
      case 134:
        return ChatMessageMsg.decode(readValue(buffer)!);
      case 135:
        return ChatOptionsMsg.decode(readValue(buffer)!);
      case 136:
        return UsageMsg.decode(readValue(buffer)!);
      case 137:
        return ChatResultMsg.decode(readValue(buffer)!);
      case 138:
        return LiveReadyMsg.decode(readValue(buffer)!);
      case 139:
        return LivePartialMsg.decode(readValue(buffer)!);
      case 140:
        return LiveFinalMsg.decode(readValue(buffer)!);
      case 141:
        return ChatDeltaMsg.decode(readValue(buffer)!);
      case 142:
        return VoiceListeningMsg.decode(readValue(buffer)!);
      case 143:
        return VoiceHeardMsg.decode(readValue(buffer)!);
      case 144:
        return VoiceThinkingMsg.decode(readValue(buffer)!);
      case 145:
        return VoiceReplyMsg.decode(readValue(buffer)!);
      case 146:
        return VoiceDoneMsg.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

const StandardMethodCodec pigeonMethodCodec = StandardMethodCodec(_PigeonCodec());

/// Calls from Dart into the plugin's Kotlin code.
