/// One channel per session, selected with Pigeon's `instanceName`
/// (= session id).
/// Returns a broadcast [Stream] of events from the `sessionEvents` event channel.
///
/// Each call to this method creates a new [EventChannel], so it should
/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<SessionEventMsg> sessionEvents( {String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel sessionEventsChannel =
      EventChannel('dev.flutter.pigeon.natlas_sdk.NAtlasEventApi.sessionEvents$instanceName', pigeonMethodCodec);
  return sessionEventsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as SessionEventMsg;
  });
}
    
